 ## Totales (RF-002)
 - Dadas 2 × 50,00 Bs y 1 × 10,50 Bs, el total es 110,50 Bs, el IVA informado 14,37 Bs y el neto 96,13 Bs.

+## Descuento global (RF-006)
+- `calcularFactura(items, { descuentoGlobal })`: porcentaje entero de 0 a 100 sobre el total de las líneas;
+  sin el parámetro, o con `descuentoGlobal` omitido, el resultado es el de siempre.
+- Descuento = `Math.round(subtotal × porcentaje / 100)`; el IVA incluido y el neto se calculan sobre el total ya descontado.
+- Dadas 2 × 50,00 Bs y 1 × 10,50 Bs con 10 %: subtotal 110,50 Bs, descuento 11,05 Bs, total 99,45 Bs, IVA 12,93 Bs, neto 86,52 Bs.
+- Con 100 % el total, el IVA y el neto son 0. Fuera de 0–100, decimal o no numérico (incl. `NaN`, `null`) se rechaza con `RangeError`.
+- El resultado incluye `subtotalCentavos` y `descuentoGlobalCentavos` (0 si no hay descuento). `emitirFactura` no recibe descuento.
+
 ## Descuentos (RF-004, pendiente)
 - Dada una línea de 2 × 10,00 Bs con 10 % de descuento, el total de la línea es 18,00 Bs.
 - Un descuento fuera de 0–100 se rechaza.
diff --git a/src/factura.mjs b/src/factura.mjs
index 5d01137..c2fda5b 100644
--- a/src/factura.mjs
+++ b/src/factura.mjs
@@ -8,17 +8,22 @@ export function validarNit(nit) {
 }

 // RF-002: el IVA va incluido en el precio; se informa, no se suma.
-export function calcularFactura(items) {
+// RF-006: descuento global opcional (porcentaje entero 0–100) sobre el total de las líneas, antes del IVA informado.
+export function calcularFactura(items, { descuentoGlobal } = {}) {
   if (!Array.isArray(items) || items.length === 0) throw new Error("Una factura necesita al menos una línea");
-  let totalCentavos = 0;
+  if (descuentoGlobal !== undefined && (!Number.isInteger(descuentoGlobal) || descuentoGlobal < 0 || descuentoGlobal > 100))
+    throw new RangeError("Descuento global inválido: debe ser un entero de 0 a 100");
+  let subtotalCentavos = 0;
   for (const item of items) {
     if (!Number.isInteger(item.cantidad) || item.cantidad <= 0) throw new RangeError("Cantidad inválida");
     if (!Number.isInteger(item.precioUnitarioCentavos) || item.precioUnitarioCentavos < 0)
       throw new RangeError("Precio inválido: debe estar en centavos enteros");
-    totalCentavos += item.cantidad * item.precioUnitarioCentavos;
+    subtotalCentavos += item.cantidad * item.precioUnitarioCentavos;
   }
+  const descuentoGlobalCentavos = Math.round((subtotalCentavos * (descuentoGlobal ?? 0)) / 100);
+  const totalCentavos = subtotalCentavos - descuentoGlobalCentavos;
   const ivaCentavos = Math.round(totalCentavos * TASA_IVA);
-  return { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
+  return { subtotalCentavos, descuentoGlobalCentavos, totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
 }

 // RF-001, RF-003: emite una factura válida y congelada.
diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..c995e61 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -35,3 +35,68 @@ test("formato de montos para personas", () => {
   assert.equal(formatearBs(5), "0,05 Bs");
   assert.equal(formatearBs(-100000000), "-1.000.000,00 Bs");
 });
+
+const base = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+const solo = (centavos) => [{ cantidad: 1, precioUnitarioCentavos: centavos }];
+
+test("RF-006 T-01: sin descuento global los totales no cambian", () => {
+  for (const f of [calcularFactura(base), calcularFactura(base, {}), calcularFactura(base, { descuentoGlobal: undefined })]) {
+    assert.equal(f.totalCentavos, 11050);
+    assert.equal(f.ivaCentavos, 1437);
+    assert.equal(f.netoCentavos, 9613);
+    assert.equal(f.subtotalCentavos, 11050);
+    assert.equal(f.descuentoGlobalCentavos, 0);
+  }
+});
+
+test("RF-006 T-02: 10 % sobre 11050", () => {
+  const f = calcularFactura(base, { descuentoGlobal: 10 });
+  assert.equal(f.totalCentavos, 9945);
+  assert.equal(f.ivaCentavos, 1293);
+  assert.equal(f.netoCentavos, 8652);
+});
+
+test("RF-006 T-03: 100 % y 0 % son válidos", () => {
+  const total = calcularFactura(base, { descuentoGlobal: 100 });
+  assert.equal(total.totalCentavos, 0);
+  assert.equal(total.ivaCentavos, 0);
+  assert.equal(total.netoCentavos, 0);
+  assert.deepEqual(calcularFactura(base, { descuentoGlobal: 0 }), calcularFactura(base));
+});
+
+test("RF-006 T-04: descuentos inválidos lanzan RangeError", () => {
+  for (const d of [-1, 101, 10.5, "10", NaN, null]) {
+    assert.throws(() => calcularFactura(base, { descuentoGlobal: d }), RangeError, `descuentoGlobal ${String(d)}`);
+  }
+});
+
+test("RF-006 T-05: redondeo del descuento al centavo", () => {
+  const a = calcularFactura(solo(1001), { descuentoGlobal: 5 });
+  assert.equal(a.descuentoGlobalCentavos, 50);
+  assert.equal(a.totalCentavos, 951);
+  assert.equal(a.ivaCentavos, 124);
+  assert.equal(a.netoCentavos, 827);
+  const b = calcularFactura(solo(1010), { descuentoGlobal: 5 });
+  assert.equal(b.descuentoGlobalCentavos, 51);
+  assert.equal(b.totalCentavos, 959);
+});
+
+test("RF-006 T-06: forma exacta del resultado", () => {
+  assert.deepEqual(calcularFactura(base, { descuentoGlobal: 10 }), {
+    subtotalCentavos: 11050,
+    descuentoGlobalCentavos: 1105,
+    totalCentavos: 9945,
+    ivaCentavos: 1293,
+    netoCentavos: 8652,
+  });
+});
+
+test("RF-006 T-07: emitirFactura no cambia", () => {
+  const f = emitirFactura({ numero: 1, nit: "1234567", razonSocial: "X", items: base });
+  assert.ok(Object.isFrozen(f));
+  assert.equal(f.estado, "emitida");
+  assert.equal(f.totalCentavos, 11050);
+});
